import{_ as l,l as n,o as e,c as i,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"半平面交","description":"","frontmatter":{"title":"半平面交","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/half-plane-intersection.md","filePath":"cs/half-plane-intersection.md","lastUpdated":1789023840000}'),c={name:"cs/half-plane-intersection.md"};function _(u,a,f,m,P,E){const o=n("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="半平面交" tabindex="-1">半平面交 <a class="header-anchor" href="#半平面交" aria-label="Permalink to &quot;半平面交&quot;">​</a></h1><div class="epigraph"><p>线性不等式的可行域是凸多边形（可无界）；增量或极角排序 + 双端队列 $O(n\\log n)$ 求出交。</p><footer>—— 据 Preparata, Muller 与计算几何教材；LP 二维对照[单纯形](/cs/simplex) 整理</footer></div><p>上一课<a href="/cs/segment-intersection">线段相交</a>报交点。半平面 \\(ax+by\\le c\\) 的交是凸集。缺口是求交多边形：极角排序后 deque 增量，类似 Andrew 凸包对偶。不重写 BO。后课 Voronoi。二维 LP 也可随机增量线性期望。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个半平面，交可能空、点、多边形、无界。对偶：点凸包 \\(\\leftrightarrow\\) 半平面交。算法：排序方向，维护凸链，新半平面切掉尾部。\\(O(n\\log n)\\)。</p><p>缺口是凸可行域边界，不是单纯形表（高维）。</p><h3 id="无界要加哨兵" tabindex="-1">无界要加哨兵 <a class="header-anchor" href="#无界要加哨兵" aria-label="Permalink to &quot;无界要加哨兵&quot;">​</a></h3><p>无穷射线用很大边界或方向无穷。空交要检测矛盾（平行反向）。不要假定一定有界。</p><p><span class="marginnote">计算几何教材半平面交。Megiddo/Seidel 二维 LP 线性。后课 Voronoi 可看成半平面交的轨迹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规范化（左侧为可行）。按法向极角排序。双端队列增量。输出顶点。</p>',11)),(e(),s(h,null,{default:r(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20HP%5B%22%E5%8D%8A%E5%B9%B3%E9%9D%A2%22%5D%20--%3E%20ANG%5B%22%E6%9E%81%E8%A7%92%E6%8E%92%E5%BA%8F%22%5D%0A%20%20ANG%20--%3E%20DQ%5B%22deque%20%E5%88%87%E5%B0%BE%22%5D%0A%20%20DQ%20--%3E%20POLY%5B%22%E5%87%B8%E4%BA%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>平行半平面先合并最紧。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>新约束只切凸多边形的连续一段，故从两端弹。与 Graham 对偶。与 LP：目标可当再一个扫描方向。高维半空间交是 \\(O(n^{\\lfloor d/2\\rfloor})\\) 级，本课平面。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维多面体。浮点切点收到鲁棒性课。后课默认：平面半平面交 \\(O(n\\log n)\\)。下一课 Voronoi 与 Delaunay。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半平面交 = 凸多边形（可空、可无界）。</li><li>极角 + deque \\(O(n\\log n)\\)。</li><li>对偶于点凸包。</li><li>出处：计算几何标准算法；二维 LP 对照。</li></ul>',7))])}const b=l(c,[["render",_]]);export{q as __pageData,b as default};
